window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f6327fa261bf64f5"]={"versions": [{"id": "FIG-f6327fa261bf64f5", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Software-Architektur- und Datenflussdiagramm eines Verbrennungsmotor-Steuerungssystems (Internal Combustion Engine Control System) im Kontext der AUTOSAR Timing Extensions (TPS_TimingExtensions). Das Diagramm veranschaulicht die Zerlegung einer Steuergeräte-Software in logische Funktionsblöcke (Sensorik, Anwendungssoftware, Aktorik) sowie die End-to-End-Signal- und Timing-Pfade über mehrere Software-Komponenten (SW-Cs) und Runnable Entities hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Gesamtsystem kapselt Software-Komponenten (graue Rechtecke) mit enthaltenen Runnable Entities (dunkelblaue Blöcke) und Ports:</p>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstellen (Systemgrenze links):</strong> Port-Stack zur Aufnahme physikalischer Signale (u. a. Fahrpedal, Luftmasse, Drosselklappe).\n</li><li><strong>Sensor Reading (Gruppierung):</strong>\n<ul class=\"fig-list\"><li><code>Accelerator Pedal Sensor</code>: SW-C mit Eingangs-/Ausgangsport und Runnable Entity.\n</li><li><code>Mass Airflow Sensor</code>: SW-C mit Eingangs-/Ausgangsport und Runnable Entity.\n</li><li><code>Throttle Sensor</code>: SW-C mit Eingangs-/Ausgangsport und Runnable Entity.\n</li></ul>\n</li><li><strong>Application Software (zentrale Gruppierung, durch Trennlinie unterbrochen dargestellt):</strong>\n<ul class=\"fig-list\"><li>Mehrere generische <code>Application SW-C</code>-Komponenten mit jeweils einer Runnable Entity sowie variierender Anzahl von Eingangs- und Ausgangsports (u. a. Verzweigungen und Zusammenführungen von Datenströmen).\n</li></ul>\n</li><li><strong>Aktorik-Bereich:</strong>\n<ul class=\"fig-list\"><li><code>Camshaft Synchronous Actuator Control</code> (Gruppierung): Enthält <code>Injection Actuator</code> und <code>Ignition Actuator</code>, jeweils mit mehreren Eingangsports, einer Runnable Entity und einem Ausgangsport.\n</li><li><code>Throttle Actuator</code>: SW-C mit Eingangs- und Ausgangsport sowie Runnable Entity.\n</li></ul>\n</li><li><strong>Ausgangsschnittstellen (Systemgrenze rechts):</strong> Drei Hauptausgangsports für Stellsignale (Einspritzung, Zündung, Drosselklappenstellung).\n</li><li><strong>Legende:</strong> Dunkelblaues Rechteck repräsentiert eine <code>Runnable Entity</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die hellblauen Richtungspfeile kennzeichnen durchgängige Signal- und Ursache-Wirkungsketten (Timing Paths / Event Chains):</p>\n<ol class=\"fig-list\"><li><strong>Fahrpedalpfad:</strong> Führt vom Eingang über den <code>Accelerator Pedal Sensor</code> in die <code>Application SW-C</code>, verzweigt bzw. fusioniert mit weiteren Sensorpfaden und speist die winkel-/nockenwellensynchrone Einspritzregelung (<code>Injection Actuator</code>) zum Systemausgang.\n</li><li><strong>Luftmassen- und Drosselklappenpfad:</strong> Signale des <code>Mass Airflow Sensor</code> und <code>Throttle Sensor</code> laufen in eine gemeinsame <code>Application SW-C</code>, werden dort verarbeitet, aufgeteilt und steuern nach Durchlaufen weiterer Applikations-SW-Cs die Zündungsaktorik (<code>Ignition Actuator</code>) an.\n</li><li><strong>Drosselklappenstellerpfad:</strong> Ein unterer Signalpfad verläuft von der zentralen Anwendungslogik direkt über die <code>Throttle Actuator</code>-SW-C zum Stellsignalausgang.\n</li></ol>\n<p class=\"fig-p\">Pfade zeigen synchrone wie asynchrone Kopplungen, Verzweigungen (1-zu-n) und Bündelungen (n-zu-1) innerhalb der Rechenkette.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als semantisches Referenzbeispiel für die Modellierung von AUTOSAR Timing Extensions (<code>TimingDescriptionSpec</code>, <code>EndToEndEventChain</code>, <code>LatencyTimingConstraint</code>). Es verdeutlicht die Notwendigkeit zur Spezifikation von Signallaufzeiten und Ausführungsfristen über verschiedene Ausführungsdomänen (periodisch/zeitgesteuert vs. winkelsynchron/ereignisgesteuert). Entwickler müssen bei der Ableitung von Timing-Modellen die Pfadsegmentierung über SW-C-Grenzen, RTE-Kommunikationspuffer und Task-/Runnable-Aktivierungen berücksichtigen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-01184d6c0ad1e2c7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Software-Architektur- und Datenflussdiagramm eines Verbrennungsmotor-Steuerungssystems (Internal Combustion Engine Control System) im Kontext der AUTOSAR Timing Extensions (TPS_TimingExtensions). Das Diagramm veranschaulicht die Zerlegung einer Steuergeräte-Software in logische Funktionsblöcke (Sensorik, Anwendungssoftware, Aktorik) sowie die End-to-End-Signal- und Timing-Pfade über mehrere Software-Komponenten (SW-Cs) und Runnable Entities hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Gesamtsystem kapselt Software-Komponenten (graue Rechtecke) mit enthaltenen Runnable Entities (dunkelblaue Blöcke) und Ports:</p>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstellen (Systemgrenze links):</strong> Port-Stack zur Aufnahme physikalischer Signale (u. a. Fahrpedal, Luftmasse, Drosselklappe).\n</li><li><strong>Sensor Reading (Gruppierung):</strong>\n<ul class=\"fig-list\"><li><code>Accelerator Pedal Sensor</code>: SW-C mit Eingangs-/Ausgangsport und Runnable Entity.\n</li><li><code>Mass Airflow Sensor</code>: SW-C mit Eingangs-/Ausgangsport und Runnable Entity.\n</li><li><code>Throttle Sensor</code>: SW-C mit Eingangs-/Ausgangsport und Runnable Entity.\n</li></ul>\n</li><li><strong>Application Software (zentrale Gruppierung, durch Trennlinie unterbrochen dargestellt):</strong>\n<ul class=\"fig-list\"><li>Mehrere generische <code>Application SW-C</code>-Komponenten mit jeweils einer Runnable Entity sowie variierender Anzahl von Eingangs- und Ausgangsports (u. a. Verzweigungen und Zusammenführungen von Datenströmen).\n</li></ul>\n</li><li><strong>Aktorik-Bereich:</strong>\n<ul class=\"fig-list\"><li><code>Camshaft Synchronous Actuator Control</code> (Gruppierung): Enthält <code>Injection Actuator</code> und <code>Ignition Actuator</code>, jeweils mit mehreren Eingangsports, einer Runnable Entity und einem Ausgangsport.\n</li><li><code>Throttle Actuator</code>: SW-C mit Eingangs- und Ausgangsport sowie Runnable Entity.\n</li></ul>\n</li><li><strong>Ausgangsschnittstellen (Systemgrenze rechts):</strong> Drei Hauptausgangsports für Stellsignale (Einspritzung, Zündung, Drosselklappenstellung).\n</li><li><strong>Legende:</strong> Dunkelblaues Rechteck repräsentiert eine <code>Runnable Entity</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die hellblauen Richtungspfeile kennzeichnen durchgängige Signal- und Ursache-Wirkungsketten (Timing Paths / Event Chains):</p>\n<ol class=\"fig-list\"><li><strong>Fahrpedalpfad:</strong> Führt vom Eingang über den <code>Accelerator Pedal Sensor</code> in die <code>Application SW-C</code>, verzweigt bzw. fusioniert mit weiteren Sensorpfaden und speist die winkel-/nockenwellensynchrone Einspritzregelung (<code>Injection Actuator</code>) zum Systemausgang.\n</li><li><strong>Luftmassen- und Drosselklappenpfad:</strong> Signale des <code>Mass Airflow Sensor</code> und <code>Throttle Sensor</code> laufen in eine gemeinsame <code>Application SW-C</code>, werden dort verarbeitet, aufgeteilt und steuern nach Durchlaufen weiterer Applikations-SW-Cs die Zündungsaktorik (<code>Ignition Actuator</code>) an.\n</li><li><strong>Drosselklappenstellerpfad:</strong> Ein unterer Signalpfad verläuft von der zentralen Anwendungslogik direkt über die <code>Throttle Actuator</code>-SW-C zum Stellsignalausgang.\n</li></ol>\n<p class=\"fig-p\">Pfade zeigen synchrone wie asynchrone Kopplungen, Verzweigungen (1-zu-n) und Bündelungen (n-zu-1) innerhalb der Rechenkette.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als semantisches Referenzbeispiel für die Modellierung von AUTOSAR Timing Extensions (<code>TimingDescriptionSpec</code>, <code>EndToEndEventChain</code>, <code>LatencyTimingConstraint</code>). Es verdeutlicht die Notwendigkeit zur Spezifikation von Signallaufzeiten und Ausführungsfristen über verschiedene Ausführungsdomänen (periodisch/zeitgesteuert vs. winkelsynchron/ereignisgesteuert). Entwickler müssen bei der Ableitung von Timing-Modellen die Pfadsegmentierung über SW-C-Grenzen, RTE-Kommunikationspuffer und Task-/Runnable-Aktivierungen berücksichtigen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f6327fa261bf64f5", "to": "FIG-01184d6c0ad1e2c7", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
